-- Extend only the isolated fixture, never production.
CREATE TABLE IF NOT EXISTS public.categories(id uuid PRIMARY KEY);
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT now();
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS cancelled_by text;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS cancellation_reason text;
ALTER TABLE public.gift_products ADD COLUMN IF NOT EXISTS is_active boolean DEFAULT true;
ALTER TABLE public.buy_x_get_y ADD COLUMN IF NOT EXISTS name text;
ALTER TABLE public.buy_x_get_y ADD COLUMN IF NOT EXISTS description text;
ALTER TABLE public.buy_x_get_y ADD COLUMN IF NOT EXISTS buy_type text;
ALTER TABLE public.buy_x_get_y ADD COLUMN IF NOT EXISTS buy_quantity integer DEFAULT 2;
ALTER TABLE public.buy_x_get_y ADD COLUMN IF NOT EXISTS get_type text DEFAULT 'cheapest_free';
ALTER TABLE public.buy_x_get_y ADD COLUMN IF NOT EXISTS get_product_id uuid REFERENCES public.products(id);
ALTER TABLE public.buy_x_get_y ADD COLUMN IF NOT EXISTS get_variant_id uuid REFERENCES public.product_variants(id);
ALTER TABLE public.buy_x_get_y ADD COLUMN IF NOT EXISTS get_discount_type text DEFAULT 'free';
ALTER TABLE public.buy_x_get_y ADD COLUMN IF NOT EXISTS get_discount_value numeric DEFAULT 100;
ALTER TABLE public.buy_x_get_y ADD COLUMN IF NOT EXISTS apply_to text DEFAULT 'all';
ALTER TABLE public.buy_x_get_y ADD COLUMN IF NOT EXISTS max_per_order integer;
ALTER TABLE public.buy_x_get_y ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT now();
ALTER TABLE public.free_gifts ADD COLUMN IF NOT EXISTS name text;
ALTER TABLE public.free_gifts ADD COLUMN IF NOT EXISTS description text;
ALTER TABLE public.free_gifts ADD COLUMN IF NOT EXISTS gift_product_id uuid REFERENCES public.products(id);
ALTER TABLE public.free_gifts ADD COLUMN IF NOT EXISTS gift_product_ref_id uuid REFERENCES public.gift_products(id);
ALTER TABLE public.free_gifts ADD COLUMN IF NOT EXISTS gift_variant_id uuid REFERENCES public.product_variants(id);
ALTER TABLE public.free_gifts ADD COLUMN IF NOT EXISTS gift_quantity integer DEFAULT 1;
ALTER TABLE public.free_gifts ADD COLUMN IF NOT EXISTS trigger_type text;
ALTER TABLE public.free_gifts ADD COLUMN IF NOT EXISTS trigger_threshold numeric DEFAULT 0;
ALTER TABLE public.free_gifts ADD COLUMN IF NOT EXISTS min_cart_amount numeric;
ALTER TABLE public.free_gifts ADD COLUMN IF NOT EXISTS apply_to text DEFAULT 'all';
ALTER TABLE public.free_gifts ADD COLUMN IF NOT EXISTS max_per_order integer;
ALTER TABLE public.free_gifts ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT now();
CREATE TABLE IF NOT EXISTS public.bxgy_buy_products(bxgy_id uuid REFERENCES public.buy_x_get_y(id) ON DELETE CASCADE,product_id uuid REFERENCES public.products(id),PRIMARY KEY(bxgy_id,product_id));
CREATE TABLE IF NOT EXISTS public.bxgy_get_products(LIKE public.bxgy_buy_products INCLUDING ALL);
CREATE TABLE IF NOT EXISTS public.bxgy_buy_categories(bxgy_id uuid REFERENCES public.buy_x_get_y(id) ON DELETE CASCADE,category_id uuid REFERENCES public.categories(id),PRIMARY KEY(bxgy_id,category_id));
CREATE TABLE IF NOT EXISTS public.bxgy_buy_brands(bxgy_id uuid REFERENCES public.buy_x_get_y(id) ON DELETE CASCADE,brand text,PRIMARY KEY(bxgy_id,brand));
CREATE TABLE IF NOT EXISTS public.free_gift_products(free_gift_id uuid REFERENCES public.free_gifts(id) ON DELETE CASCADE,product_id uuid REFERENCES public.products(id),PRIMARY KEY(free_gift_id,product_id));
CREATE TABLE IF NOT EXISTS public.free_gift_categories(free_gift_id uuid REFERENCES public.free_gifts(id) ON DELETE CASCADE,category_id uuid REFERENCES public.categories(id),PRIMARY KEY(free_gift_id,category_id));
CREATE TABLE IF NOT EXISTS public.free_gift_brands(free_gift_id uuid REFERENCES public.free_gifts(id) ON DELETE CASCADE,brand text,PRIMARY KEY(free_gift_id,brand));
GRANT ALL ON public.categories TO service_role;
